import re

def iso_duration_seconds(s):
    if not s:
        raise ValueError("Empty string")
    if s[0] != 'P':
        raise ValueError(f"Must start with P: {s!r}")
    if len(s) == 1:
        raise ValueError(f"'P' only not allowed: {s!r}")

    week_match = re.match(r'^P(\d+(?:\.\d+)?)W$', s)
    if week_match:
        weeks = float(week_match.group(1))
        return weeks * 7 * 86400

    rest_after_P = s[1:]
    has_T = 'T' in rest_after_P

    if has_T:
        t_idx = rest_after_P.index('T')
        day_part = rest_after_P[:t_idx]
        time_part = rest_after_P[t_idx+1:]

        total_seconds = 0.0
        has_count = False

        if day_part:
            if 'M' in day_part:
                raise ValueError(f"Months (M) before T are not allowed in {s!r}")
            day_match = re.match(r'^(\d+(?:\.\d+)?)D$', day_part)
            if not day_match:
                raise ValueError(f"Invalid day part: {day_part!r} in {s!r}")
            day_count = float(day_match.group(1))
            total_seconds += day_count * 86400
            has_count = True

        remaining_time = time_part

        hour_match = re.match(r'^(\d+(?:\.\d+)?)H', remaining_time)
        if hour_match:
            total_seconds += float(hour_match.group(1)) * 3600
            remaining_time = remaining_time[hour_match.end():]
            has_count = True

        minute_match = re.match(r'^(\d+(?:\.\d+)?)M', remaining_time)
        if minute_match:
            total_seconds += float(minute_match.group(1)) * 60
            remaining_time = remaining_time[minute_match.end():]
            has_count = True

        if remaining_time:
            if remaining_time.endswith('S'):
                sec_num = remaining_time[:-1]
                if sec_num == '':
                    raise ValueError(f"Second count must have digits before S in {s!r}")
                sec_match = re.match(r'^(\d+(?:\.\d+)?)$', sec_num)
                if sec_match:
                    total_seconds += float(sec_match.group(1))
                    has_count = True
                    remaining_time = remaining_time[sec_match.end():]
                else:
                    raise ValueError(f"Invalid second part: {remaining_time!r} in {s!r}")
            else:
                raise ValueError(f"Invalid time part remaining '{remaining_time}' in {s!r}")

        if not has_count:
            raise ValueError(f"No count present after T in {s!r}")

        return total_seconds

    else:
        day_match = re.match(r'^P(\d+(?:\.\d+)?)D$', s)
        if day_match:
            day_count = float(day_match.group(1))
            return day_count * 86400
        raise ValueError(f"Invalid format: {s!r}")


# Verify all spec examples
examples = [
    ("PT0S", 0),
    ("PT1H30M", 5400),
    ("P1DT2H", 93600),
    ("P1W", 604800),
    ("PT0.5S", 0.5),
    ("P2DT3H4M5.25S", 183845.25),
]

error_examples = ["", "P", "PT", "1H", "P1H"]

print("Verifying all spec examples pass:")
all_ok = True
for s, expected in examples:
    result = iso_duration_seconds(s)
    if result != expected:
        print(f"FAIL: {s!r} -> {result}, expected {expected}")
        all_ok = False
    else:
        print(f"PASS: {s!r} -> {result}")

for s in error_examples:
    try:
        iso_duration_seconds(s)
        print(f"FAIL: {s!r} should have raised ValueError")
        all_ok = False
    except ValueError:
        print(f"PASS: {s!r} raises ValueError")

if all_ok:
    print("\nALL TESTS PASSED")
else:
    print("\nSOME TESTS FAILED")

